import React from 'react';
import './logIn.css';
import foobarImage from './foobar.jpg';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';
import UsersList from '../UsersList';



function LogIn() {
    
    const navigate = useNavigate();
    const users = [
        { id : 1, email : "user1", password : "pass1" },
        { id : 2, email : "user2", password : "pass2" },
        { id : 3, email : "user3", password : "pass3" }
        ];
         const [email, setEmail] = useState('');
         const [password, setPassword] = useState('');

    const handleLogInClick = () => {
        
        const usersList = UsersList.getUsers(); 
        
               
            const validUser = usersList.find(user => user.email === email && user.password === password);
    
          if (validUser) {
            navigate('homePage');
          }
        
      };
      
    const handleSignupClick = () => {
      navigate('SignUp');
    };
    
    return (
        <header id="header">
      <div className="layer"></div>
      <div className="main">
        <div className="left">
          <img src={foobarImage} alt="" />
          <p>Connect with friends and the world around you on Foobar.</p>
        </div>
        <div className="right">
          <form>
            <div className="form_body">
              <input
                type="text"
                placeholder="Email or phone number"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
              <button className="login" onClick={handleLogInClick}>
                Log In
              </button>
              <p className="forget">forgot password?</p>
              <hr />
              <button className="create" onClick={handleSignupClick}>
                Create new account
              </button>
            </div>
          </form>
          <p className="foot">
            <span>Create a Page</span> for a celebrity, brand, or business.
          </p>
        </div>
      </div>
    </header>

);
}

export default LogIn;
